82	impl LockContext {
83	    pub fn new_heartbeat(&mut self) -> Arc<AtomicBool> {
84	        let is_set = Arc::new(AtomicBool::new(true));
85	        let heartbeat = Heartbeat {
86	            is_set: Arc::downgrade(&is_set),
87	            last_heartbeat: Instant::now(),
88	        };
89	
90	        let i = self.heartbeat_index;
91	        self.heartbeats.insert(i, heartbeat);
92	
93	        self.heartbeat_index = i.checked_add(1).unwrap();
94	
95	        is_set
96	    }
