480	/// A thread pool for running fork-join workloads.
481	#[derive(Debug)]
482	pub struct ThreadPool {
483	    context: Arc<Context>,
484	    worker_handles: Vec<JoinHandle<()>>,
485	    heartbeat_handle: Option<JoinHandle<()>>,
486	}
487	
488	impl ThreadPool {
489	    /// Crates a new thread pool with default `Config`.
490	    ///
491	    /// # Examples
492	    ///
493	    /// ```
494	    /// # use chili::ThreadPool;
495	    /// let _tp = ThreadPool::new();
496	    /// ```
497	    pub fn new() -> Self {
498	        Self::with_config(Config::default())
499	    }
500	
501	    /// Creates a new thread pool with `config`.
502	    ///
503	    /// # Examples
504	    ///
505	    /// ```
506	    /// # use std::{num::NonZero, time::Duration};
507	    /// # use chili::{Config, ThreadPool};
508	    /// let _tp = ThreadPool::with_config(Config {
509	    ///     thread_count: Some(NonZero::new(1).unwrap()),
510	    ///     heartbeat_interval: Duration::from_micros(50),
511	    /// });
512	    /// ```
513	    pub fn with_config(config: Config) -> Self {
514	        let thread_count = config
515	            .thread_count
516	            .or_else(|| thread::available_parallelism().ok())
517	            .map(|thread_count| thread_count.get() - 1)
518	            .unwrap_or_default();
519	        let worker_barrier = Arc::new(Barrier::new(thread_count + 1));
520	
521	        let context = Arc::new(Context {
522	            lock: Mutex::new(LockContext::default()),
523	            job_is_ready: Condvar::new(),
524	            scope_created_from_thread_pool: Condvar::new(),
525	        });
526	
527	        let worker_handles = (0..thread_count)
528	            .map(|_| {
529	                let context = context.clone();
530	                let barrier = worker_barrier.clone();
531	                thread::spawn(move || {
532	                    execute_worker(context, barrier);
533	                })
534	            })
535	            .collect();
536	
537	        worker_barrier.wait();
538	
539	        Self {
540	            context: context.clone(),
541	            worker_handles,
542	            heartbeat_handle: Some(thread::spawn(move || {
543	                execute_heartbeat(context, config.heartbeat_interval, thread_count);
544	            })),
545	        }
546	    }
547	
548	    /// Sets the global thread pool to this one.
549	    ///
550	    /// The global thread pool can only be set once. Any subsequent call will
551	    /// return the thread pool back.
552	    ///
553	    /// # Examples
554	    ///
555	    /// ```
556	    /// # use std::{num::NonZero, time::Duration};
557	    /// # use chili::{Config, ThreadPool};
558	    /// ThreadPool::with_config(Config {
559	    ///     thread_count: Some(NonZero::new(1).unwrap()),
560	    ///     heartbeat_interval: Duration::from_micros(50),
561	    /// })
562	    /// .set_global()
563	    /// .unwrap();
564	    /// ```
565	    pub fn set_global(self) -> Result<(), Self> {
566	        GLOBAL_THREAD_POOL.set(self)
567	    }
568	
569	    /// Returns the global thread pool.
570	    ///
571	    /// # Examples
572	    ///
573	    /// ```
574	    /// # use chili::ThreadPool;
575	    /// let mut s = ThreadPool::global().scope();
576	    ///
577	    /// let mut vals = [0; 2];
578	    /// let (left, right) = vals.split_at_mut(1);
579	    ///
580	    /// s.join(|_| left[0] = 1, |_| right[0] = 1);
581	    ///
582	    /// assert_eq!(vals, [1; 2]);
583	    /// ```
584	    pub fn global() -> &'static ThreadPool {
585	        GLOBAL_THREAD_POOL.get_or_init(ThreadPool::new)
586	    }
587	
588	    /// Returns a `Scope`d object that you can run fork-join workloads on.
589	    ///
590	    /// # Examples
591	    ///
592	    /// ```
593	    /// # use chili::ThreadPool;
594	    /// let mut tp = ThreadPool::new();
595	    /// let mut s = tp.scope();
596	    ///
597	    /// let mut vals = [0; 2];
598	    /// let (left, right) = vals.split_at_mut(1);
